//     compiler refuses, which is drift pointing the other way.
//   * **No new pinned dependency.** PRD 5.12 pins every version per compiler
//     release; a dependency whose CEL reading changed in a patch would move the
//     runtime's semantics without moving the compiler's.
//
// # Values
//
// | CEL | here |
// |---|---|
// | `int` | `bigint` |
// | `uint` | `bigint` (tagged by `CelUint`) |
// | `double` | `number` |
// | `bool`, `string`, `null` | `boolean`, `string`, `null` |
// | `bytes` | `Uint8Array` |
// | `list` | `CelValue[]` |
// | `map` | `CelMap` — keyed by type *and* value, so `1` and `'1'` stay apart |
//
// # Numbers, and where their type comes from
//
// JSON cannot tell `1` from `1.0`, and CEL must: `1 + 2.5` is an error in the
// specification and in both implementations. So a value entering an expression
// is converted through a **shape** (below) derived from the declaration the
// value came from — a state channel's type, an agent's output schema, a flow's
// input schema. `type: integer` becomes a `bigint` and `type: number` a
// `number`, whatever the JSON looked like. Where no shape is known (`"any"`),
// an integral JSON number is read as an `int`, which is the corpus's own rule.

/** A uint, which JavaScript has no separate type for. */
export class CelUint {
  readonly value: bigint;

  constructor(value: bigint) {
    this.value = value;
  }
}

/** A CEL map: keyed by the key's type and value, so `1` and `'1'` differ. */
export class CelMap {
  readonly entries: Map<string, { key: CelValue; value: CelValue }>;

  constructor(entries?: Iterable<[CelValue, CelValue]>) {
    this.entries = new Map();
    for (const [key, value] of entries ?? []) {
      this.entries.set(mapKey(key), { key, value });
    }
  }

  get size(): number {
    return this.entries.size;
  }

  has(key: CelValue): boolean {
    return this.entries.has(mapKey(key));
  }

  get(key: CelValue): CelValue | undefined {
    return this.entries.get(mapKey(key))?.value;
  }

  set(key: CelValue, value: CelValue): void {
    this.entries.set(mapKey(key), { key, value });
  }

  keys(): CelValue[] {
    return [...this.entries.values()].map((entry) => entry.key);
  }
}

/** Every value an expression can hold. */
export type CelValue =
  | null
  | boolean
  | bigint
  | CelUint
  | number
  | string
  | Uint8Array
  | CelValue[]
  | CelMap;

/**
 * What a JSON-shaped value means, so a number's CEL type is the declared one.
 *
 * `"any"` is the fallback the corpus's own rule describes: an integral number
 * is an `int` and everything else a `double`.
 */
export type Shape =
  | "any"
  | "int"
  | "uint"
  | "double"
  | "string"
  | "bool"
  | "null"
  | "bytes"
  | { readonly properties: Readonly<Record<string, Shape>>; readonly rest?: Shape }
  | { readonly items: Shape };

/** Raised by every failure this module reports. */
export class CelError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CelError";
  }
}

const INT_MIN = -(2n ** 63n);
const INT_MAX = 2n ** 63n - 1n;
const UINT_MAX = 2n ** 64n - 1n;

function mapKey(key: CelValue): string {
  if (typeof key === "string") return `s:${key}`;
  if (typeof key === "bigint") return `i:${key}`;
  if (key instanceof CelUint) return `u:${key.value}`;
  if (typeof key === "boolean") return `b:${key}`;
  throw new CelError(`a map key must be a string, an integer, or a boolean, found ${typeName(key)}`);
}

/** The CEL type name of a value, for a diagnostic. */
export function typeName(value: CelValue): string {
  if (value === null) return "null";
  if (typeof value === "boolean") return "bool";
  if (typeof value === "bigint") return "int";
  if (value instanceof CelUint) return "uint";
  if (typeof value === "number") return "double";
  if (typeof value === "string") return "string";
  if (value instanceof Uint8Array) return "bytes";
  if (Array.isArray(value)) return "list";
  if (value instanceof CelMap) return "map";
  return "unknown";
}

// ---------------------------------------------------------------------------
// Binding: a JSON-shaped value in, a CEL value out
// ---------------------------------------------------------------------------

/**
 * Read one JavaScript value as the CEL value its declaration says it is.
 *
 * `undefined` is preserved as `undefined` rather than converted, because
 * absence is a runtime property every read has to be able to report on
 * (Decision D110): an object property that is not there is not `null`.
 */
export function bind(value: unknown, shape: Shape = "any"): CelValue | undefined {
  if (value === undefined) return undefined;
  if (value === null) return null;
  if (typeof value === "bigint") return value;
  if (value instanceof Uint8Array) return value;
  if (value instanceof CelMap || value instanceof CelUint) return value;

  if (typeof value === "number") {
    if (shape === "int") {
      if (!Number.isInteger(value)) {
        throw new CelError(`\`${value}\` is declared an integer and is not one`);
      }
      return BigInt(value);
    }
    if (shape === "uint") return new CelUint(BigInt(value));
    if (shape === "double") return value;
    return Number.isInteger(value) ? BigInt(value) : value;
  }
  if (typeof value === "boolean" || typeof value === "string") return value;

  if (Array.isArray(value)) {
    const items = typeof shape === "object" && "items" in shape ? shape.items : "any";
    return value.map((item) => {
      const bound = bind(item, items);
      if (bound === undefined) {
        throw new CelError("a list element is absent");
      }
      return bound;
    });
  }

  if (typeof value === "object") {
    const properties = typeof shape === "object" && "properties" in shape ? shape.properties : {};
    const rest = typeof shape === "object" && "rest" in shape ? (shape.rest ?? "any") : "any";
    const map = new CelMap();
    for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
      const bound = bind(entry, properties[key] ?? rest);
      if (bound !== undefined) map.set(key, bound);
    }
    return map;
  }

  throw new CelError(`a ${typeof value} is not a value an expression can read`);
}

/**
 * A CEL value as plain JSON-shaped JavaScript: what a binding writes to state
 * or serializes into a request.
 *
 * An `int` outside JavaScript's exactly-representable range is refused rather
 * than rounded — the evaluator is exact by construction and a silent fold here
 * would give that away at the one point the value leaves it.
 */
export function toJson(value: CelValue): unknown {
  if (value === null || typeof value === "boolean" || typeof value === "string") return value;
  if (typeof value === "number") return value;
  if (typeof value === "bigint" || value instanceof CelUint) {
    const held = typeof value === "bigint" ? value : value.value;
    if (held > BigInt(Number.MAX_SAFE_INTEGER) || held < BigInt(Number.MIN_SAFE_INTEGER)) {
      throw new CelError(
        `the integer ${held} is outside the range JavaScript represents exactly, so it cannot be written out`,
      );
    }
    return Number(held);
  }
  if (value instanceof Uint8Array) return [...value];
  if (Array.isArray(value)) return value.map(toJson);
  if (value instanceof CelMap) {
    const object: Record<string, unknown> = {};
    for (const entry of value.entries.values()) {
      object[typeof entry.key === "string" ? entry.key : String(toJson(entry.key))] = toJson(
        entry.value,
      );
    }
    return object;
  }
  return value;
}

// ---------------------------------------------------------------------------
// The parser
// ---------------------------------------------------------------------------

type Token =
  | { kind: "punct"; text: string; at: number }
  | { kind: "ident"; text: string; at: number }
  | { kind: "int"; value: bigint; at: number }
  | { kind: "uint"; value: bigint; at: number }
  | { kind: "double"; value: number; at: number }
  | { kind: "string"; value: string; at: number }
  | { kind: "bytes"; value: Uint8Array; at: number }
  | { kind: "end"; at: number };

const PUNCTUATION = [
  "==",
  "!=",
  "<=",
  ">=",
  "&&",
  "||",
  "(",
  ")",
  "[",
  "]",
  "{",
  "}",
  ".",
  ",",
  ":",
  "?",
  "+",
  "-",
  "*",
  "/",
  "%",
  "!",
  "<",
  ">",
];

function isIdentStart(character: string): boolean {
  return /[A-Za-z_]/.test(character);
}

function isIdentPart(character: string): boolean {
  return /[A-Za-z0-9_]/.test(character);
}

function lex(source: string): Token[] {
  const tokens: Token[] = [];
  let at = 0;
  while (at < source.length) {
    const character = source[at]!;
    if (/\s/.test(character)) {
      at += 1;
      continue;
    }
    if (character === "/" && source[at + 1] === "/") {
      while (at < source.length && source[at] !== "\n") at += 1;
      continue;
    }

    // A string or bytes literal, with its optional `r` and `b` prefixes.
    const literal = readString(source, at);
    if (literal !== undefined) {
      tokens.push(literal.token);
      at = literal.next;
      continue;
    }

    if (/[0-9]/.test(character) || (character === "." && /[0-9]/.test(source[at + 1] ?? ""))) {
      const number = readNumber(source, at);
      tokens.push(number.token);
      at = number.next;
      continue;
    }

    if (isIdentStart(character)) {
      let end = at;
      while (end < source.length && isIdentPart(source[end]!)) end += 1;
      tokens.push({ kind: "ident", text: source.slice(at, end), at });
      at = end;
      continue;
    }

    const punctuation = PUNCTUATION.find((candidate) => source.startsWith(candidate, at));
    if (punctuation === undefined) {
      throw new CelError(`unexpected character \`${character}\` at offset ${at}`);
    }
    tokens.push({ kind: "punct", text: punctuation, at });
    at += punctuation.length;
  }
  tokens.push({ kind: "end", at: source.length });
  return tokens;
}

function readNumber(source: string, at: number): { token: Token; next: number } {
  const start = at;
  if (source.startsWith("0x", at) || source.startsWith("0X", at)) {
    let end = at + 2;
    while (end < source.length && /[0-9A-Fa-f]/.test(source[end]!)) end += 1;
    const digits = source.slice(at, end);
    if (source[end] === "u" || source[end] === "U") {
      return { token: { kind: "uint", value: BigInt(digits), at: start }, next: end + 1 };
    }
    return { token: { kind: "int", value: BigInt(digits), at: start }, next: end };
  }
  let end = at;
  while (end < source.length && /[0-9]/.test(source[end]!)) end += 1;
  let double = false;
  if (source[end] === ".") {
    double = true;
    end += 1;
    while (end < source.length && /[0-9]/.test(source[end]!)) end += 1;
  }
  if (source[end] === "e" || source[end] === "E") {
    double = true;
    end += 1;
    if (source[end] === "+" || source[end] === "-") end += 1;
    while (end < source.length && /[0-9]/.test(source[end]!)) end += 1;
  }
  const text = source.slice(start, end);
  if (!double && (source[end] === "u" || source[end] === "U")) {
    return { token: { kind: "uint", value: BigInt(text), at: start }, next: end + 1 };
  }
  if (double) {
    return { token: { kind: "double", value: Number(text), at: start }, next: end };
  }
  return { token: { kind: "int", value: BigInt(text), at: start }, next: end };
}

/**
 * The code point an `\xHH`, `\uHHHH`, `\UHHHHHHHH` or `\OOO` escape names.
 *
 * The digits are checked before they are read, rather than handed to
 * `Number.parseInt` and trusted: `parseInt` stops at the first character it
 * cannot read and answers `NaN` for none at all, so `'\uZZZZ'` would become a
 * silent NUL where the compiler's front-end refuses the literal outright. The
 * surrogate range and everything past `U+10FFFF` are refused for the same
 * reason — `String.fromCodePoint` would answer a lone surrogate for the first
 * and throw a bare `RangeError` for the second.
 */
function escapedCode(
  source: string,
  at: number,
  count: number,
  radix: 8 | 16,
  label: string,
): number {
  const digits = source.slice(at, at + count);
  const legal = radix === 16 ? /^[0-9a-fA-F]+$/ : /^[0-7]+$/;
  if (digits.length !== count || !legal.test(digits)) {
    throw new CelError(
      `the escape \`\\${label}\` wants ${count} ${radix === 16 ? "hexadecimal" : "octal"} digits`,
    );
  }
  const code = Number.parseInt(digits, radix);
  if (code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) {
    throw new CelError(
      `the escape \`\\${label}\` names U+${code.toString(16).toUpperCase()}, which is not a Unicode code point`,
    );
  }
  return code;
}

/**
 * One string or bytes literal (CEL's *Lexis*, grammar 4.1).
 *
 * The escape table is the specification's, which is the same table the pinned
 * `cel` crate implements: `\a \b \f \n \r \t \v \\ \' \" \` \?`, `\xHH`,
 * `\uHHHH`, `\UHHHHHHHH`, and `\OOO` — **three** octal digits whose first is
 * `0`–`3`. There is no `\0`, and no escape may be invented here: an evaluator
 * that reads one the compiler's front-end refuses is drift pointing the other
 * way, and one that reads `'\011'` as anything but a tab answers a guard
 * differently from the validator that admitted it.
 *
 * A `b'…'` literal accumulates **bytes** rather than the UTF-8 of a string:
 * `\xFF` and `\377` are the byte `0xFF` there, where encoding the code point
 * `U+00FF` would have produced two. `\u`/`\U` name code points and so are
 * refused inside one, as the specification refuses them.
 */
function readString(source: string, at: number): { token: Token; next: number } | undefined {
  let cursor = at;
  let bytes = false;
  let raw = false;
  if (/[bB]/.test(source[cursor] ?? "") && /[rR'"]/.test(source[cursor + 1] ?? "")) {
    bytes = true;
    cursor += 1;
  }
  if (/[rR]/.test(source[cursor] ?? "") && /['"]/.test(source[cursor + 1] ?? "")) {
    raw = true;
    cursor += 1;
  }
  const quote = source[cursor];
  if (quote !== "'" && quote !== '"') return undefined;
  const triple = source[cursor + 1] === quote && source[cursor + 2] === quote;
  const terminator = triple ? quote.repeat(3) : quote;
  cursor += terminator.length;

  let text = "";
  const octets: number[] = [];
  // What a piece of the literal contributes: a byte sequence inside `b'…'`, the
  // characters themselves otherwise.
  const push = (value: string) => {
    if (bytes) {
      for (const octet of new TextEncoder().encode(value)) octets.push(octet);
    } else {
      text += value;
    }
  };
  // A `\xHH` or `\OOO` escape, which is one **byte** inside `b'…'` and the code
  // point of the same value in a string. Both spellings top out at 255.
  const pushCode = (code: number) => {
    if (bytes) {
      octets.push(code);
    } else {
      text += String.fromCodePoint(code);
    }
  };

  while (cursor < source.length) {
    if (source.startsWith(terminator, cursor)) {
      cursor += terminator.length;
      const token: Token = bytes
        ? { kind: "bytes", value: Uint8Array.from(octets), at }
        : { kind: "string", value: text, at };
      return { token, next: cursor };
    }
    const character = source[cursor]!;
    if (!raw && character === "\\") {
      const escaped = source[cursor + 1];
      cursor += 2;
      switch (escaped) {
        case "a":
          push("\u0007");
          break;
        case "b":
          push("\b");
          break;
        case "f":
          push("\f");
          break;
        case "n":
          push("\n");
          break;
        case "r":
          push("\r");
          break;
        case "t":
          push("\t");
          break;
        case "v":
          push("\v");
          break;
        case "\\":
        case "'":
        case '"':
        case "`":
        case "?":
          push(escaped);
          break;
        case "u":
        case "U": {
          const count = escaped === "u" ? 4 : 8;
          if (bytes) {
            throw new CelError(`\`\\${escaped}\` names a code point, which a bytes literal has no`);
          }
          text += String.fromCodePoint(escapedCode(source, cursor, count, 16, escaped));
          cursor += count;
          break;
        }
        case "x": {
          pushCode(escapedCode(source, cursor, 2, 16, "x"));
          cursor += 2;
          break;
        }
        // `\OOO`: three octal digits whose first is `0`–`3`, so the value is a
        // byte. The leading digit was consumed with the backslash, so the escape
        // is re-read from where it began.
        case "0":
        case "1":
        case "2":
        case "3": {
          pushCode(escapedCode(source, cursor - 1, 3, 8, "OOO"));
          cursor += 2;
          break;
        }
        default:
          throw new CelError(`unknown escape \`\\${escaped ?? ""}\``);
      }
      continue;
    }
    if (!triple && (character === "\n" || character === "\r")) {
      throw new CelError("a single-quoted string does not survive a line break");
    }
    // A whole code point, not a UTF-16 unit: a surrogate half handed to
    // `TextEncoder` on its own encodes as U+FFFD, so `b'👍'` would be four
    // replacement bytes rather than the four the character is made of.
    const point = String.fromCodePoint(source.codePointAt(cursor)!);
    push(point);
    cursor += point.length;
  }
  throw new CelError("an unterminated string literal");
}

type Expr =
  | { kind: "literal"; value: CelValue }
  | { kind: "ident"; name: string }
  | { kind: "select"; operand: Expr; field: string }
  | { kind: "index"; operand: Expr; key: Expr }
  | { kind: "call"; target?: Expr; name: string; args: Expr[] }
  | { kind: "list"; items: Expr[] }
  | { kind: "map"; entries: { key: Expr; value: Expr }[] }
  | { kind: "unary"; operator: string; operand: Expr }
  | { kind: "binary"; operator: string; left: Expr; right: Expr }
  | { kind: "conditional"; condition: Expr; then: Expr; otherwise: Expr };

class Parser {
  private readonly tokens: Token[];
  private at = 0;

  constructor(source: string) {
    this.tokens = lex(source);
  }

  parse(): Expr {
    const expression = this.conditional();
    const token = this.peek();
    if (token.kind !== "end") {
      throw new CelError(`unexpected input at offset ${token.at}`);
    }
    return expression;
  }

  private peek(): Token {
    return this.tokens[this.at]!;
  }

  private next(): Token {
    const token = this.tokens[this.at]!;
    this.at += 1;
    return token;
  }

  private eat(text: string): boolean {
    const token = this.peek();
    if (token.kind === "punct" && token.text === text) {
      this.at += 1;
      return true;
    }
    return false;
  }

  private expect(text: string): void {
    if (!this.eat(text)) {
      throw new CelError(`expected \`${text}\` at offset ${this.peek().at}`);
    }
  }

  private conditional(): Expr {
    const condition = this.or();
    if (!this.eat("?")) return condition;
    const then = this.conditional();
    this.expect(":");
    return { kind: "conditional", condition, then, otherwise: this.conditional() };
  }

  private or(): Expr {
    let left = this.and();
    while (this.eat("||")) {
      left = { kind: "binary", operator: "||", left, right: this.and() };
    }
    return left;
  }

  private and(): Expr {
    let left = this.relation();
    while (this.eat("&&")) {
      left = { kind: "binary", operator: "&&", left, right: this.relation() };
    }
    return left;
  }

  private relation(): Expr {
    let left = this.additive();
    for (;;) {
      const token = this.peek();
      if (token.kind === "ident" && token.text === "in") {
        this.at += 1;
        left = { kind: "binary", operator: "in", left, right: this.additive() };
        continue;
      }
      if (
        token.kind === "punct" &&
        ["==", "!=", "<", "<=", ">", ">="].includes(token.text)
      ) {
        this.at += 1;
        left = { kind: "binary", operator: token.text, left, right: this.additive() };
        continue;
      }
      return left;
    }
  }

  private additive(): Expr {
    let left = this.multiplicative();
    for (;;) {
      const token = this.peek();
      if (token.kind === "punct" && (token.text === "+" || token.text === "-")) {
        this.at += 1;
        left = { kind: "binary", operator: token.text, left, right: this.multiplicative() };
        continue;
      }
      return left;
    }
  }

  private multiplicative(): Expr {
    let left = this.unary();
    for (;;) {
      const token = this.peek();
      if (token.kind === "punct" && ["*", "/", "%"].includes(token.text)) {
        this.at += 1;
        left = { kind: "binary", operator: token.text, left, right: this.unary() };
        continue;
      }
      return left;
    }
  }

  private unary(): Expr {
    const token = this.peek();
    if (token.kind === "punct" && (token.text === "!" || token.text === "-")) {
      this.at += 1;
      return { kind: "unary", operator: token.text, operand: this.unary() };
    }
    return this.member();
  }

  private member(): Expr {
    let operand = this.primary();
    for (;;) {
      if (this.eat(".")) {
        const token = this.next();
        if (token.kind !== "ident") {
          throw new CelError(`expected a field name at offset ${token.at}`);
        }
        if (this.eat("(")) {
          operand = { kind: "call", target: operand, name: token.text, args: this.arguments() };
          continue;
        }
        operand = { kind: "select", operand, field: token.text };
        continue;
      }
      if (this.eat("[")) {
        const key = this.conditional();
        this.expect("]");
        operand = { kind: "index", operand, key };
        continue;
      }
      return operand;
    }
  }

  private arguments(): Expr[] {
    const args: Expr[] = [];
    if (this.eat(")")) return args;
    for (;;) {
      args.push(this.conditional());
      if (this.eat(",")) continue;
      this.expect(")");
      return args;
    }
  }

  private primary(): Expr {
    const token = this.next();
    if (token.kind === "int") return { kind: "literal", value: token.value };
    if (token.kind === "uint") return { kind: "literal", value: new CelUint(token.value) };
    if (token.kind === "double") return { kind: "literal", value: token.value };
    if (token.kind === "string") return { kind: "literal", value: token.value };
    if (token.kind === "bytes") return { kind: "literal", value: token.value };
    if (token.kind === "ident") {
      if (token.text === "true") return { kind: "literal", value: true };
      if (token.text === "false") return { kind: "literal", value: false };
      if (token.text === "null") return { kind: "literal", value: null };
      if (this.eat("(")) {
        return { kind: "call", name: token.text, args: this.arguments() };
      }
      return { kind: "ident", name: token.text };
    }
    if (token.kind === "punct" && token.text === "(") {
      const inner = this.conditional();
      this.expect(")");
      return inner;
    }
    if (token.kind === "punct" && token.text === "[") {
      const items: Expr[] = [];
      if (this.eat("]")) return { kind: "list", items };
      for (;;) {
        items.push(this.conditional());
        if (this.eat(",")) {
          if (this.eat("]")) return { kind: "list", items };
          continue;
        }
        this.expect("]");
        return { kind: "list", items };
      }
    }
    if (token.kind === "punct" && token.text === "{") {
      const entries: { key: Expr; value: Expr }[] = [];
      if (this.eat("}")) return { kind: "map", entries };
      for (;;) {
        const key = this.conditional();
        this.expect(":");
        entries.push({ key, value: this.conditional() });
        if (this.eat(",")) {
          if (this.eat("}")) return { kind: "map", entries };
          continue;
        }
        this.expect("}");
        return { kind: "map", entries };
      }
    }
    throw new CelError(`unexpected token at offset ${token.at}`);
  }
}

// ---------------------------------------------------------------------------
// The evaluator
// ---------------------------------------------------------------------------

interface Scope {
  readonly roots: ReadonlyMap<string, CelValue>;
  readonly bindings: ReadonlyMap<string, CelValue>;
}

const COMPREHENSIONS = new Set(["all", "exists", "exists_one", "filter", "map"]);

function lookup(scope: Scope, name: string): CelValue {
  if (scope.bindings.has(name)) return scope.bindings.get(name)!;
  if (scope.roots.has(name)) return scope.roots.get(name)!;
  throw new CelError(`\`${name}\` is not a root in scope here`);
}

function withBinding(scope: Scope, name: string, value: CelValue): Scope {
  const bindings = new Map(scope.bindings);
  bindings.set(name, value);
  return { roots: scope.roots, bindings };
}

function member(operand: CelValue, field: string, spelling: string): CelValue {
  if (operand instanceof CelMap) {
    const found = operand.get(field);
    if (found === undefined) {
      throw new CelError(`\`${spelling}\` is not present: nothing has supplied it`);
    }
    return found;
  }
  throw new CelError(`\`${spelling}\` selects a field of a ${typeName(operand)}, which has none`);
}

/**
 * Whether a selection is present (grammar 4.1's `has()`).
 *
 * A value with no fields at all is a refusal rather than a `false`, and the
 * wording is `member`'s because it is the same mistake: `has(x.f)` where `x` is
 * a list asks a question a list has no answer to, and CEL's own definitions give
 * the macro no overload there. Answering `false` would make the evaluator accept
 * an expression the validator refuses (`type-mismatch`) and the pinned Rust
 * column errors on — a superset of the surface, which is the drift this module's
 * header calls out by name.
 */
function present(operand: CelValue, field: string, spelling: string): boolean {
  if (operand instanceof CelMap) return operand.has(field);
  throw new CelError(`\`${spelling}\` selects a field of a ${typeName(operand)}, which has none`);
}

/**
 * The spelling of a path, for the message an absent read fails with.
 *
 * An index whose key is a **string literal** is spelled as written, because that
 * key is usually the whole content of the diagnostic: the absent read a caller
 * of a generated app meets first is a trigger's
 * `session_key: "payload.headers['x-session']"` against a request that carried
 * no such header, and `payload.headers[…] is not present` names everything about
 * that mistake except the one thing the caller can act on. It is also the
 * spelling the validator's own column already uses for this case — `Path` in
 * `src/cel/mod.rs` records a literal key and prints it — so the two
 * interpreters name one sub-path one way (PRD G3, grammar 4.1).
 *
 * A computed key stays `[…]`: its value is this run's rather than the
 * expression's, and printing it would put run data into a message a reader
 * matches against their spec.
 */
function spell(expression: Expr): string {
  switch (expression.kind) {
    case "ident":
      return expression.name;
    case "select":
      return `${spell(expression.operand)}.${expression.field}`;
    case "index": {
      const key = expression.key;
      // `JSON.stringify` is a double-quoted CEL string literal carrying only
      // escapes this module's own lexer reads back (`\"`, `\\`, `\uXXXX`), so
      // the spelling round-trips rather than merely reads.
      const written =
        key.kind === "literal" && typeof key.value === "string"
          ? JSON.stringify(key.value)
          : "…";
      return `${spell(expression.operand)}[${written}]`;
    }
    default:
      return "an expression";
  }
}

function isNumber(value: CelValue): value is bigint | number | CelUint {
  return typeof value === "bigint" || typeof value === "number" || value instanceof CelUint;
}

function asDouble(value: bigint | number | CelUint): number {
  if (typeof value === "number") return value;
  return Number(typeof value === "bigint" ? value : value.value);
}

/** Two numeric values, in the same CEL type, or `undefined` when they differ. */
function sameNumeric(
  left: CelValue,
  right: CelValue,
): { kind: "int" | "uint" | "double"; left: bigint | number; right: bigint | number } | undefined {
  if (typeof left === "bigint" && typeof right === "bigint") {
    return { kind: "int", left, right };
  }
  if (left instanceof CelUint && right instanceof CelUint) {
    return { kind: "uint", left: left.value, right: right.value };
  }
  if (typeof left === "number" && typeof right === "number") {
    return { kind: "double", left, right };
  }
  return undefined;
}

function checkedInt(value: bigint, operator: string): bigint {
  if (value < INT_MIN || value > INT_MAX) {
    throw new CelError(`\`${operator}\` overflowed the range of an int`);
  }
  return value;
}

function checkedUint(value: bigint, operator: string): CelUint {
  if (value < 0n || value > UINT_MAX) {
    throw new CelError(`\`${operator}\` overflowed the range of a uint`);
  }
  return new CelUint(value);
}

function arithmetic(operator: string, left: CelValue, right: CelValue): CelValue {
  if (operator === "+") {
    if (typeof left === "string" && typeof right === "string") return left + right;
    if (Array.isArray(left) && Array.isArray(right)) return [...left, ...right];
    if (left instanceof Uint8Array && right instanceof Uint8Array) {
      const joined = new Uint8Array(left.length + right.length);
      joined.set(left);
      joined.set(right, left.length);
      return joined;
    }
  }
  const pair = sameNumeric(left, right);
  if (pair === undefined) {
    throw new CelError(
      `\`${operator}\` has no overload for a ${typeName(left)} and a ${typeName(right)}`,
    );
  }
  if (pair.kind === "double") {
    const a = pair.left as number;
    const b = pair.right as number;
    switch (operator) {
      case "+":
        return a + b;
      case "-":
        return a - b;
      case "*":
        return a * b;
      case "/":
        return a / b;
      case "%":
        throw new CelError("`%` has no overload for two doubles");
      default:
        throw new CelError(`unknown operator \`${operator}\``);
    }
  }
  const a = pair.left as bigint;
  const b = pair.right as bigint;
  let answer: bigint;
  switch (operator) {
    case "+":
      answer = a + b;
      break;
    case "-":
      answer = a - b;
      break;
    case "*":
      answer = a * b;
      break;
    case "/":
      if (b === 0n) throw new CelError("division by zero");
      answer = a / b;
      break;
    case "%":
      if (b === 0n) throw new CelError("modulus by zero");
      answer = a % b;
      break;
    default:
      throw new CelError(`unknown operator \`${operator}\``);
  }
  return pair.kind === "int" ? checkedInt(answer, operator) : checkedUint(answer, operator);
}

function equal(left: CelValue, right: CelValue): boolean {
  if (isNumber(left) && isNumber(right)) {
    const pair = sameNumeric(left, right);
    if (pair !== undefined) return pair.left === pair.right;
    // CEL compares across the numeric types: `1.0 == 1` is true.
    return asDouble(left) === asDouble(right);
  }
  if (left === null || right === null) return left === right;
  if (typeof left !== typeof right && !(Array.isArray(left) && Array.isArray(right))) {
    if (left instanceof CelMap !== right instanceof CelMap) return false;
    if (left instanceof Uint8Array !== right instanceof Uint8Array) return false;
  }
  if (typeof left === "boolean" || typeof left === "string") return left === right;
  if (left instanceof Uint8Array && right instanceof Uint8Array) {
    return left.length === right.length && left.every((byte, index) => byte === right[index]);
  }
  if (Array.isArray(left) && Array.isArray(right)) {
    return left.length === right.length && left.every((item, index) => equal(item, right[index]!));
  }
  if (left instanceof CelMap && right instanceof CelMap) {
    if (left.size !== right.size) return false;
    for (const [key, entry] of left.entries) {
      const other = right.entries.get(key);
      if (other === undefined || !equal(entry.value, other.value)) return false;
    }
    return true;
  }
  return false;
}

/**
 * Order two strings the way the Rust column does: by **code point**.
 *
 * JavaScript's own `<` compares UTF-16 **code units**, and the two orders are not
 * the same one. A code point at or above U+10000 is stored as a surrogate pair
 * whose leading unit is in U+D800..U+DBFF, so `<` sorts every astral character
 * *below* every BMP character in U+E000..U+FFFF — while a Rust `String`, which is
 * UTF-8, sorts by byte and therefore by code point, putting them above. `'�'
 * < '\u{1F600}'` is `true` there and `false` under a bare `<`, which is a legal
 * guard the two columns would route opposite ways.
 *
 * Comparing code points *is* comparing UTF-8 bytes: the encoding is order
 * preserving, so no encoder is needed and none is used. A lone surrogate has no
 * UTF-8 encoding and cannot occur in a Rust `String` at all, so where one appears
 * this orders it by its own value — there is no other column to agree with.
 */
function compareStrings(left: string, right: string): number {
  if (left === right) return 0;
  const a = [...left];
  const b = [...right];
  const shared = Math.min(a.length, b.length);
  for (let index = 0; index < shared; index += 1) {
    const x = a[index]!.codePointAt(0)!;
    const y = b[index]!.codePointAt(0)!;
    if (x !== y) return x < y ? -1 : 1;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

function order(operator: string, left: CelValue, right: CelValue): boolean {
  let comparison: number;
  if (isNumber(left) && isNumber(right)) {
    const pair = sameNumeric(left, right);
    if (pair === undefined) {
      const a = asDouble(left);
      const b = asDouble(right);
      comparison = a < b ? -1 : a > b ? 1 : 0;
    } else {
      comparison = pair.left < pair.right ? -1 : pair.left > pair.right ? 1 : 0;
    }
  } else if (typeof left === "string" && typeof right === "string") {
    comparison = compareStrings(left, right);
  } else if (typeof left === "boolean" && typeof right === "boolean") {
    comparison = left === right ? 0 : left ? 1 : -1;
  } else {
    throw new CelError(
      `\`${operator}\` has no overload for a ${typeName(left)} and a ${typeName(right)}`,
    );
  }
  switch (operator) {
    case "<":
      return comparison < 0;
    case "<=":
      return comparison <= 0;
    case ">":
      return comparison > 0;
    default:
      return comparison >= 0;
  }
}

function membership(element: CelValue, container: CelValue): boolean {
  if (Array.isArray(container)) return container.some((item) => equal(item, element));
  if (container instanceof CelMap) return container.has(element);
  throw new CelError(`\`in\` has no overload for a ${typeName(container)} on the right`);
}

function size(value: CelValue): bigint {
  if (typeof value === "string") return BigInt([...value].length);
  if (value instanceof Uint8Array) return BigInt(value.length);
  if (Array.isArray(value)) return BigInt(value.length);
  if (value instanceof CelMap) return BigInt(value.size);
  throw new CelError(`\`size\` has no overload for a ${typeName(value)}`);
}

function expectString(value: CelValue, what: string): string {
  if (typeof value !== "string") {
    throw new CelError(`\`${what}\` expects a string, found a ${typeName(value)}`);
  }
  return value;
}

function expectBool(value: CelValue, what: string): boolean {
  if (typeof value !== "boolean") {
    throw new CelError(`${what} expects a bool, found a ${typeName(value)}`);
  }
  return value;
}

function comprehension(name: string, range: CelValue, args: Expr[], scope: Scope): CelValue {
  const first = args[0];
  if (first === undefined || first.kind !== "ident") {
    throw new CelError(`\`${name}\` takes a binding name as its first argument`);
  }
  const variable = first.name;
  const items = Array.isArray(range)
    ? range
    : range instanceof CelMap
      ? range.keys()
      : (() => {
          throw new CelError(`\`${name}\` ranges over a list, not a ${typeName(range)}`);
        })();

  const test = (item: CelValue, expression: Expr): boolean =>
    expectBool(evaluateExpr(expression, withBinding(scope, variable, item)), `\`${name}\``);

  switch (name) {
    case "all": {
      const predicate = args[1]!;
      return items.every((item) => test(item, predicate));
    }
    case "exists": {
      const predicate = args[1]!;
      return items.some((item) => test(item, predicate));
    }
    case "exists_one": {
      const predicate = args[1]!;
      return items.filter((item) => test(item, predicate)).length === 1;
    }
    case "filter": {
      const predicate = args[1]!;
      return items.filter((item) => test(item, predicate));
    }
    default: {
      // `map(x, transform)` and `map(x, predicate, transform)`.
      const predicate = args.length === 3 ? args[1]! : undefined;
      const transform = args.length === 3 ? args[2]! : args[1]!;
      const kept = predicate === undefined ? items : items.filter((item) => test(item, predicate));
      return kept.map((item) => evaluateExpr(transform, withBinding(scope, variable, item)));
    }
  }
}

function call(expression: Extract<Expr, { kind: "call" }>, scope: Scope): CelValue {
  const { name, target, args } = expression;

  if (name === "has") {
    if (target !== undefined || args.length !== 1 || args[0]!.kind !== "select") {
      throw new CelError("`has()` asks whether one selection is present — `has(state.totals.fixed)`");
    }
    const selection = args[0] as Extract<Expr, { kind: "select" }>;
    return present(evaluateExpr(selection.operand, scope), selection.field, spell(selection));
  }

  if (COMPREHENSIONS.has(name) && target !== undefined) {
    return comprehension(name, evaluateExpr(target, scope), args, scope);
  }

  const operands = [
    ...(target === undefined ? [] : [evaluateExpr(target, scope)]),
    ...args.map((argument) => evaluateExpr(argument, scope)),
  ];

  switch (name) {
    case "size": {
      if (operands.length !== 1) {
        throw new CelError("`size` takes one argument — `size(state.tasks)` or `state.tasks.size()`");
      }
      return size(operands[0]!);
    }
    case "startsWith":
    case "endsWith":
    case "contains": {
      // Receiver-only, by CEL's standard definitions: `matches` below is the one
      // string predicate the specification also gives a global overload, which
      // is why the compiler's own arity table accepts `(receiver, 1)` alone for
      // these three. Accepting `startsWith(s, p)` here would run an expression
      // `validate` refuses (`no form it has`) and the pinned Rust column cannot
      // evaluate either.
      if (target === undefined || args.length !== 1) {
        throw new CelError(
          `\`${name}\` takes one argument on the string it tests — \`state.draft.${name}('a')\``,
        );
      }
      const subject = expectString(operands[0]!, name);
      const argument = expectString(operands[1]!, name);
      if (name === "startsWith") return subject.startsWith(argument);
      if (name === "endsWith") return subject.endsWith(argument);
      return subject.includes(argument);
    }
    case "matches": {
      if (operands.length !== 2) {
        throw new CelError(
          "`matches` is written `state.draft.matches('^a')` or `matches(state.draft, '^a')`",
        );
      }
      const subject = expectString(operands[0]!, name);
      const pattern = expectString(operands[1]!, name);
      return new RegExp(pattern).test(subject);
    }
    default:
      throw new CelError(`\`${name}\` is not a function this expression surface supports`);
  }
}

function evaluateExpr(expression: Expr, scope: Scope): CelValue {
  switch (expression.kind) {
    case "literal":
      return expression.value;
    case "ident":
      return lookup(scope, expression.name);
    case "select":
      return member(
        evaluateExpr(expression.operand, scope),
        expression.field,
        spell(expression),
      );
    case "index": {
      const operand = evaluateExpr(expression.operand, scope);
      const key = evaluateExpr(expression.key, scope);
      if (Array.isArray(operand)) {
        if (typeof key !== "bigint" && !(key instanceof CelUint)) {
          throw new CelError(`a list index is an integer, found a ${typeName(key)}`);
        }
        const index = Number(typeof key === "bigint" ? key : key.value);
        if (index < 0 || index >= operand.length) {
          throw new CelError(`index ${index} is outside a list of ${operand.length}`);
        }
        return operand[index]!;
      }
      if (operand instanceof CelMap) {
        const found = operand.get(key);
        if (found === undefined) {
          throw new CelError(`\`${spell(expression)}\` is not present: nothing has supplied it`);
        }
        return found;
      }
      throw new CelError(`a ${typeName(operand)} cannot be indexed`);
    }
    case "call":
      return call(expression, scope);
    case "list":
      return expression.items.map((item) => evaluateExpr(item, scope));
    case "map": {
      const map = new CelMap();
      for (const entry of expression.entries) {
        map.set(evaluateExpr(entry.key, scope), evaluateExpr(entry.value, scope));
      }
      return map;
    }
    case "unary": {
      const operand = evaluateExpr(expression.operand, scope);
      if (expression.operator === "!") {
        return !expectBool(operand, "`!`");
      }
      if (typeof operand === "bigint") return checkedInt(-operand, "-");
      if (typeof operand === "number") return -operand;
      throw new CelError(`unary \`-\` has no overload for a ${typeName(operand)}`);
    }
    case "conditional": {
      const condition = expectBool(evaluateExpr(expression.condition, scope), "the condition of `?:`");
      return evaluateExpr(condition ? expression.then : expression.otherwise, scope);
    }
    default: {
      const { operator, left, right } = expression;
      // CEL's logical operators are **commutative in the presence of errors**:
      // `false && <error>` and `<error> && false` are both `false`, and the same
      // for `true` under `||`. An evaluator that only short-circuits answers the
      // first and throws on the second, which is a real difference — a guard
      // reading an `optional:` property that is absent, conjoined with something
      // already false, is exactly the shape (Decision D110's read failure, under
      // grammar 7.3's guard). Both implementations of this project answer the
      // specification's way; `tests/property_conformance.rs` is what found it.
      if (operator === "&&" || operator === "||") {
        const absorbing = operator === "&&" ? false : true;
        let held: unknown;
        try {
          if (expectBool(evaluateExpr(left, scope), `\`${operator}\``) === absorbing) {
            return absorbing;
          }
        } catch (error) {
          held = error;
        }
        try {
          if (expectBool(evaluateExpr(right, scope), `\`${operator}\``) === absorbing) {
            return absorbing;
          }
        } catch (error) {
          // The left-hand error is the one reported when both sides fail: an
          // author reads an expression left to right.
          throw held ?? error;
        }
        if (held !== undefined) throw held;
        return !absorbing;
      }
      const a = evaluateExpr(left, scope);
      const b = evaluateExpr(right, scope);
      switch (operator) {
        case "==":
          return equal(a, b);
        case "!=":
          return !equal(a, b);
        case "<":
        case "<=":
        case ">":
        case ">=":
          return order(operator, a, b);
        case "in":
          return membership(a, b);
        default:
          return arithmetic(operator, a, b);
      }
    }
  }
}

/** One parsed expression, kept so a router does not re-parse on every pass. */
const PARSED = new Map<string, Expr>();

function parse(source: string): Expr {
  const cached = PARSED.get(source);
  if (cached !== undefined) return cached;
  const expression = new Parser(source).parse();
  PARSED.set(source, expression);
  return expression;
}

/** The roots one expression reads, already bound. */
export type Roots = Readonly<Record<string, CelValue | undefined>>;

/**
 * Evaluate one expression against its roots.
 *
 * A root bound to `undefined` is one the site does not supply — the absent
 * `execution.item_index` outside a `map` dispatch is the case grammar 4.1
 * names — and reading it fails the evaluation rather than answering null.
 */
export function evaluate(source: string, roots: Roots): CelValue {
  const bound = new Map<string, CelValue>();
  for (const [name, value] of Object.entries(roots)) {
    if (value !== undefined) bound.set(name, value);
  }
  return evaluateExpr(parse(source), { roots: bound, bindings: new Map() });
}

/**
 * Evaluate one expression whose declared result type is `bool` — every edge
 * guard (grammar 4.1).
 */
export function evaluateGuard(source: string, roots: Roots): boolean {
  const answer = evaluate(source, roots);
  if (typeof answer !== "boolean") {
    throw new CelError(`the guard \`${source}\` answered a ${typeName(answer)} rather than a bool`);
  }
  return answer;
}

/** Evaluate one expression and hand back plain JSON-shaped JavaScript. */
export function evaluateJson(source: string, roots: Roots): unknown {
  return toJson(evaluate(source, roots));
}
